#!/bin/bash
set -e

# Audit trail for failed registration attempts. Logged at the app
# layer (separate write, persists regardless of the RPC's own
# transaction rolling back) rather than inside register_patient
# itself, to avoid touching the just-tested gap-safe UHID fix.
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "app/(main)/patients"
echo "" | base64 -d > "app/(main)/patients/actions.js"
echo "Wrote app/(main)/patients/actions.js"

git add "app/(main)/patients/actions.js"
git commit -m "Log failed registration attempts for audit purposes"
git push

echo "Done."
